<article class="journal-card"><p class="eyebrow">{{ $review->spot->area }} / {{ \App\Support\Discovery::label($review->spot->category) }}</p><h3><a href="{{ route('spots.show',$review->spot) }}#review-{{ $review->id }}">{{ $review->spot->name }}</a></h3><p>{{ \Illuminate\Support\Str::limit($review->comment,180) }}</p><div class="review-meta"><strong>{{ $review->nickname }}</strong><span class="rating">★ {{ $review->rating }}</span></div><small>{{ $review->visited_on ? $review->visited_on->format('Y.m.d').' 訪問' : '訪問日未記入' }} · {{ $review->created_at->format('Y.m.d') }} 投稿</small></article>
